public async accept(
  signal: TradeSignal,
  handler: (signal: TradeSignal) => Promise<void>,
  acknowledge: (signal: TradeSignal) => Promise<void>,
): Promise<"handled" | "duplicate"> {
  if (this.acknowledged.has(signal.messageId)) return "duplicate";
  if (!Number.isSafeInteger(signal.sequence) || signal.sequence < 0) throw new RangeError("invalid sequence");
  if (!Number.isFinite(signal.quantity) || signal.quantity <= 0) throw new RangeError("invalid quantity");
  const lane = this.lanes.get(signal.account) ?? {
    tail: Promise.resolve(),
    queued: 0,
    completedSequence: -1,
  };
  lane.queued += 1;
  let release: (() => void) | undefined;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const predecessor = lane.tail;
  lane.tail = predecessor.catch(() => undefined).then(() => gate);
  this.lanes.set(signal.account, lane);
  await predecessor.catch(() => undefined);
  try {
    if (this.acknowledged.has(signal.messageId)) return "duplicate";
    if (signal.sequence <= lane.completedSequence) {
      throw new Error(`sequence ${signal.sequence} is not newer than ${lane.completedSequence}`);
    }
    await handler(signal);
    await acknowledge(signal);
    this.acknowledged.add(signal.messageId);
    lane.completedSequence = signal.sequence;
    lane.failedSequence = undefined;
    return "handled";
  } catch (reason: unknown) {
    lane.failedSequence = signal.sequence;
    throw reason;
  } finally {
    lane.queued -= 1;
    release?.();
    if (lane.queued === 0 && this.lanes.get(signal.account) === lane) this.lanes.delete(signal.account);
  }
}

public summarizeAccountRisk(
  settlements: readonly SettlementIntent[],
  trades: readonly TradeSignal[],
  audits: readonly AuditEntry[],
  sequenceGaps: ReadonlyMap<string, readonly number[]>,
): ReadonlyMap<string, number> {
  const risk = new Map<string, number>();
  const auditSubjects = new Set(audits.map((entry) => String(entry.fields.subject ?? "")).filter(Boolean));
  for (const intent of settlements) {
    const amountRisk = Math.log10(Math.max(1, Math.abs(intent.amount)));
    const priorityRisk = Math.max(0, intent.priority - 50) / 10;
    const auditRisk = auditSubjects.has(intent.identity) ? 0 : 3;
    risk.set(intent.account, (risk.get(intent.account) ?? 0) + amountRisk + priorityRisk + auditRisk);
  }
  for (const trade of trades) {
    const directionRisk = trade.side === "sell" ? 1.2 : 1;
    const quantityRisk = Math.log2(Math.max(1, trade.quantity)) * directionRisk;
    const gapRisk = (sequenceGaps.get(trade.account)?.length ?? 0) * 2;
    const auditRisk = auditSubjects.has(trade.messageId) ? 0 : 1.5;
    risk.set(trade.account, (risk.get(trade.account) ?? 0) + quantityRisk + gapRisk + auditRisk);
  }
  return new Map([...risk.entries()].sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0])));
}
